static const CUnit cust_grumpy_o_review1_rest[] = {
    { "One star, then straight back to their screens.", cust_grumpy_o_review1_rest0, 15, 24, 0, 46 },
    { "Good company takes patience.", cust_grumpy_o_review1_rest1, 9, 81, 0, 28 },
    { "Now it is one cold star.", cust_grumpy_o_review1_rest2, 8, 23, 0, 24 },
    { "A pup gave one star. They never warmed their paws here.", cust_grumpy_o_review1_rest3, 15, 104, 0, 55 },
    { "Good company takes time.", cust_grumpy_o_review1_rest4, 8, 22, 0, 24 },
    { "The good seats take patience to earn.", cust_grumpy_o_review1_rest5, 12, 31, 0, 37 },
    { "The young forget that patience seasons everything.", cust_grumpy_o_review1_rest6, 16, 13, 0, 50 },
    { "Some kitten gave one star. They never warmed their paws here.", cust_grumpy_o_review1_rest7, 15, 26, 0, 61 },
    { "No note, no manners.", cust_grumpy_o_review1_rest8, 10, 75, 0, 20 },
    { "The nerve of one star. This cafe has never once hissed at me.", cust_grumpy_o_review1_rest9, 19, 10, 0, 61 },
    { "They never sit a spell.", cust_grumpy_o_review1_rest10, 8, 62, 0, 23 },
    { "Now it is all stars.", cust_grumpy_o_review1_rest11, 6, 12, 0, 20 },
    { "Someone forgot how to sit still.", cust_grumpy_o_review1_rest12, 10, 71, 0, 32 },
    { "One star indeed.", cust_grumpy_o_review1_rest13, 6, 20, 0, 16 },
    { "Their paws never learned stillness.", cust_grumpy_o_review1_rest14, 9, 36, 0, 35 },
    { "One star from some pup. In my day we grumbled face to face.", cust_grumpy_o_review1_rest15, 22, 0, 0, 59 },
    { "He never knew a warm windowsill.", cust_grumpy_o_review1_rest16, 13, 7, 0, 32 },
    { "They never sip, only gulp.", cust_grumpy_o_review1_rest17, 10, 94, 0, 26 },
    { "I have napped on worse floors and said nothing.", cust_grumpy_o_review1_rest18, 16, 83, 0, 47 },
    { "One star and gone. I shall nap here twice as long in protest.", cust_grumpy_o_review1_rest19, 19, 54, 0, 61 },
    { "The steam off a fresh bowl is worth more.", cust_grumpy_o_review1_rest20, 17, 38, 0, 41 },
    { "They never learned to sip slowly.", cust_grumpy_o_review1_rest21, 10, 2, 0, 33 },
    { "One star and away. They never met the kind server.", cust_grumpy_o_review1_rest22, 16, 113, 0, 50 },
    { "In my day one star meant the roof fell in.", cust_grumpy_o_review1_rest23, 16, 116, 0, 42 },
    { "The saucer was warm, the milk was kind.", cust_grumpy_o_review1_rest24, 15, 4, 0, 39 },
    { "I have said worse and still left a coin.", cust_grumpy_o_review1_rest25, 12, 115, 0, 40 },
    { "One star? The saucer here never tipped once.", cust_grumpy_o_review1_rest26, 14, 92, 0, 44 },
    { "A slow saucer teaches more.", cust_grumpy_o_review1_rest27, 12, 32, 0, 27 },
    { "One star for this fine cafe. Back home we called that ungrateful.", cust_grumpy_o_review1_rest28, 21, 3, 0, 65 },
    { "Some pup gave one star and took the best window seat.", cust_grumpy_o_review1_rest29, 17, 44, 0, 53 },
    { "The biscuits here are soft, I say.", cust_grumpy_o_review1_rest30, 14, 57, 0, 34 },
    { "A single star slapped on this warm little room. Shameful and lazy.", cust_grumpy_o_review1_rest31, 25, 21, 0, 66 },
    { "One star. Likely the pup wanted a lap with the tea.", cust_grumpy_o_review1_rest32, 19, 66, 0, 51 },
    { "They never learned to curl up.", cust_grumpy_o_review1_rest33, 10, 86, 0, 30 },
    { "Now it is a single star.", cust_grumpy_o_review1_rest34, 9, 47, 0, 24 },
    { "A sad trade.", cust_grumpy_o_review1_rest35, 6, 89, 0, 12 },
    { "Cold and quick.", cust_grumpy_o_review1_rest36, 6, 99, 0, 15 },
    { "Now every pup leaves a rating.", cust_grumpy_o_review1_rest37, 10, 53, 0, 30 },
    { "I have tipped this place more.", cust_grumpy_o_review1_rest38, 8, 114, 0, 30 },
    { "They skip the sun entirely.", cust_grumpy_o_review1_rest39, 12, 68, 0, 27 },
};
