static const CUnit mako_v_gift_ok_rest[] = {
    { "I have twelve like this. Now I have thirteen.", mako_v_gift_ok_rest0, 16, 98, 0, 45 },
    { "My ears stayed still. Good.", mako_v_gift_ok_rest1, 8, 61, 0, 27 },
    { "It's good. There. That's the whole report.", mako_v_gift_ok_rest2, 12, 109, 0, 42 },
    { "I already have one. Mine's better.", mako_v_gift_ok_rest3, 10, 0, 0, 34 },
    { "I'll use it. There. That's your reward.", mako_v_gift_ok_rest4, 14, 50, 0, 39 },
    { "I'm not thanking you twice. Once was plenty.", mako_v_gift_ok_rest5, 15, 74, 0, 44 },
    { "I could've gotten a better one. But fine.", mako_v_gift_ok_rest6, 14, 10, 0, 41 },
    { "I'll keep it. Somewhere safe. Probably.", mako_v_gift_ok_rest7, 17, 65, 0, 39 },
    { "I'm not losing composure. Watch.", mako_v_gift_ok_rest8, 12, 56, 0, 32 },
    { "Don't let it go to your head.", mako_v_gift_ok_rest9, 10, 14, 0, 29 },
    { "My ears are staying put. Good.", mako_v_gift_ok_rest10, 10, 41, 0, 30 },
    { "My ears did not move just now. Confirm that.", mako_v_gift_ok_rest11, 16, 73, 0, 44 },
    { "Relax. I'm not returning it.", mako_v_gift_ok_rest12, 13, 12, 0, 28 },
    { "You're not winning. This is a draw.", mako_v_gift_ok_rest13, 11, 71, 0, 35 },
    { "You're persistent. I respect that. Slightly.", mako_v_gift_ok_rest14, 16, 67, 0, 44 },
    { "You timed this before the match. Sneaky.", mako_v_gift_ok_rest15, 14, 117, 0, 40 },
    { "I'm not analyzing it. Much.", mako_v_gift_ok_rest16, 13, 54, 0, 27 },
    { "You brought it in one piece. Points for that.", mako_v_gift_ok_rest17, 18, 100, 0, 45 },
    { "Okay. I'll find a spot. Don't ask where.", mako_v_gift_ok_rest18, 16, 57, 0, 40 },
    { "Fine. I accept. Don't celebrate.", mako_v_gift_ok_rest19, 18, 2, 0, 32 },
    { "You're trying. I'll note that. Somewhere.", mako_v_gift_ok_rest20, 15, 30, 0, 41 },
    { "You show, you hand, you linger. Interesting.", mako_v_gift_ok_rest21, 19, 114, 0, 44 },
    { "I've analyzed it. It's adequate.", mako_v_gift_ok_rest22, 14, 17, 0, 32 },
    { "I'm not making it weird. You are.", mako_v_gift_ok_rest23, 12, 44, 0, 33 },
    { "Okay. I'll hold it while you talk. Talk fast.", mako_v_gift_ok_rest24, 18, 105, 0, 45 },
    { "Don't look at my ears. They do what they want.", mako_v_gift_ok_rest25, 13, 99, 0, 46 },
    { "I'm not thanking you twice.", mako_v_gift_ok_rest26, 7, 49, 0, 27 },
    { "Don't get used to this reaction.", mako_v_gift_ok_rest27, 11, 33, 0, 32 },
    { "What's the angle here?", mako_v_gift_ok_rest28, 9, 11, 0, 22 },
    { "Barely. Try harder next time.", mako_v_gift_ok_rest29, 11, 3, 0, 29 },
    { "That counts. Barely.", mako_v_gift_ok_rest30, 8, 16, 0, 20 },
    { "I'm not sentimental about it. It's just useful.", mako_v_gift_ok_rest31, 16, 103, 0, 47 },
    { "My ears are not reacting. See? Fine.", mako_v_gift_ok_rest32, 15, 21, 0, 36 },
    { "I'll take it. Don't make it weird.", mako_v_gift_ok_rest33, 12, 60, 0, 34 },
    { "I'll take it to my place. Show's over.", mako_v_gift_ok_rest34, 13, 95, 0, 38 },
    { "I'm not soft about it. My voice did something.", mako_v_gift_ok_rest35, 14, 112, 0, 46 },
    { "Bold move. I'll inspect it later.", mako_v_gift_ok_rest36, 14, 1, 0, 33 },
    { "I'm not blushing. Bad lighting.", mako_v_gift_ok_rest37, 12, 64, 0, 31 },
    { "I'm leaving before I say more.", mako_v_gift_ok_rest38, 9, 68, 0, 30 },
    { "I'm not moved. That's my story. Keep it.", mako_v_gift_ok_rest39, 16, 91, 0, 40 },
};
