static const CUnit mako_v_smalltalk_rest[] = {
    { "Your stance is stiff.", mako_v_smalltalk_rest0, 9, 27, 0, 21 },
    { "That is just biology.", mako_v_smalltalk_rest1, 11, 24, 0, 21 },
    { "Something good is coming.", mako_v_smalltalk_rest2, 9, 33, 0, 25 },
    { "It was bothering me. Not you.", mako_v_smalltalk_rest3, 10, 17, 0, 29 },
    { "You are proof.", mako_v_smalltalk_rest4, 6, 81, 0, 14 },
    { "We have history.", mako_v_smalltalk_rest5, 6, 73, 0, 16 },
    { "Just saying.", mako_v_smalltalk_rest6, 6, 83, 0, 12 },
    { "I am taking that as a sign.", mako_v_smalltalk_rest7, 11, 26, 0, 27 },
    { "I noticed. I always notice.", mako_v_smalltalk_rest8, 10, 64, 0, 27 },
    { "It will tip. Watch.", mako_v_smalltalk_rest9, 7, 55, 0, 19 },
    { "I need a target.", mako_v_smalltalk_rest10, 8, 18, 0, 16 },
    { "Not you. The birds.", mako_v_smalltalk_rest11, 9, 34, 0, 19 },
    { "It does what it wants.", mako_v_smalltalk_rest12, 7, 13, 0, 22 },
    { "I did it for me. It was crooked.", mako_v_smalltalk_rest13, 12, 21, 0, 32 },
    { "I tested it. For science.", mako_v_smalltalk_rest14, 11, 84, 0, 25 },
    { "Do not look at them.", mako_v_smalltalk_rest15, 6, 58, 0, 20 },
    { "I trip on purpose never.", mako_v_smalltalk_rest16, 10, 42, 0, 24 },
    { "That is your only advantage.", mako_v_smalltalk_rest17, 9, 16, 0, 28 },
    { "It is just water.", mako_v_smalltalk_rest18, 5, 37, 0, 17 },
    { "Whatever this is.", mako_v_smalltalk_rest19, 7, 32, 0, 17 },
    { "Do not look. Too late.", mako_v_smalltalk_rest20, 9, 101, 0, 22 },
    { "I knew it was you from the corner.", mako_v_smalltalk_rest21, 12, 23, 0, 34 },
    { "Yet here I am.", mako_v_smalltalk_rest22, 7, 72, 0, 14 },
    { "You are losing.", mako_v_smalltalk_rest23, 6, 51, 0, 15 },
    { "I would rather be training. You should too.", mako_v_smalltalk_rest24, 15, 3, 0, 43 },
    { "We just walk the same way.", mako_v_smalltalk_rest25, 9, 10, 0, 26 },
    { "I could still beat you at cards.", mako_v_smalltalk_rest26, 10, 14, 0, 32 },
    { "I already know every price.", mako_v_smalltalk_rest27, 7, 74, 0, 27 },
    { "My ears hate it though.", mako_v_smalltalk_rest28, 9, 44, 0, 23 },
    { "You are welcome.", mako_v_smalltalk_rest29, 7, 85, 0, 16 },
    { "It was going stale anyway. Take it.", mako_v_smalltalk_rest30, 13, 87, 0, 35 },
    { "It is distracting.", mako_v_smalltalk_rest31, 8, 90, 0, 18 },
    { "Suspiciously so. I am watching.", mako_v_smalltalk_rest32, 14, 78, 0, 31 },
    { "Your grip is off. Just saying.", mako_v_smalltalk_rest33, 13, 105, 0, 30 },
    { "That is boring.", mako_v_smalltalk_rest34, 6, 19, 0, 15 },
    { "Watch. Told you. Always right.", mako_v_smalltalk_rest35, 13, 95, 0, 30 },
    { "I am noting it. Not concerned.", mako_v_smalltalk_rest36, 12, 92, 0, 30 },
    { "Twice. Before lunch.", mako_v_smalltalk_rest37, 11, 69, 0, 20 },
    { "I am taking that as a sign.", mako_v_smalltalk_rest38, 11, 89, 0, 27 },
    { "This is me doing it anyway.", mako_v_smalltalk_rest39, 9, 93, 0, 27 },
};
