static const CUnit kuro_v_gossip_cafe_rest[] = {
    { "Shifts do the same, child.", kuro_v_gossip_cafe_rest0, 13, 70, 0, 26 },
    { "You lift cups earlier.", kuro_v_gossip_cafe_rest1, 10, 11, 0, 22 },
    { "So do you, child.", kuro_v_gossip_cafe_rest2, 9, 88, 0, 17 },
    { "You watch the door. Both see.", kuro_v_gossip_cafe_rest3, 10, 109, 0, 29 },
    { "Neither do you.", kuro_v_gossip_cafe_rest4, 7, 50, 0, 15 },
    { "So do cafe crowds.", kuro_v_gossip_cafe_rest5, 9, 99, 0, 18 },
    { "Curious.", kuro_v_gossip_cafe_rest6, 5, 107, 0, 8 },
    { "So does a good table.", kuro_v_gossip_cafe_rest7, 8, 19, 0, 21 },
    { "Fill yours gently.", kuro_v_gossip_cafe_rest8, 8, 22, 0, 18 },
    { "Good. The pond likes that sound.", kuro_v_gossip_cafe_rest9, 10, 46, 0, 32 },
    { "Heh.", kuro_v_gossip_cafe_rest10, 4, 96, 0, 4 },
    { "You mend cups and saucers, maybe.", kuro_v_gossip_cafe_rest11, 14, 17, 0, 33 },
    { "So do long shifts, I hear.", kuro_v_gossip_cafe_rest12, 10, 9, 0, 26 },
    { "Endurance is a trade.", kuro_v_gossip_cafe_rest13, 10, 47, 0, 21 },
    { "I told it you work days now.", kuro_v_gossip_cafe_rest14, 9, 55, 0, 28 },
    { "Customers do, I hear.", kuro_v_gossip_cafe_rest15, 9, 91, 0, 21 },
    { "That travels far.", kuro_v_gossip_cafe_rest16, 9, 72, 0, 17 },
    { "Sharing suits you too.", kuro_v_gossip_cafe_rest17, 9, 29, 0, 22 },
    { "You serve folks like I serve the pond. Quietly.", kuro_v_gossip_cafe_rest18, 20, 89, 0, 47 },
    { "Old nets and old cafes both hold stories.", kuro_v_gossip_cafe_rest19, 18, 74, 0, 41 },
    { "Yours tell Mocha's.", kuro_v_gossip_cafe_rest20, 7, 106, 0, 19 },
    { "Heh. Like fishing.", kuro_v_gossip_cafe_rest21, 10, 117, 0, 18 },
    { "Even a cat naps between the tides.", kuro_v_gossip_cafe_rest22, 14, 1, 0, 34 },
    { "Nor does a rush.", kuro_v_gossip_cafe_rest23, 6, 68, 0, 16 },
    { "The pond noticed.", kuro_v_gossip_cafe_rest24, 5, 105, 0, 17 },
    { "Slow hands make fine coffee.", kuro_v_gossip_cafe_rest25, 9, 24, 0, 28 },
    { "You watch the door. Both count.", kuro_v_gossip_cafe_rest26, 10, 28, 0, 31 },
    { "Reel in slowly.", kuro_v_gossip_cafe_rest27, 7, 60, 0, 15 },
    { "Rest between shifts, child.", kuro_v_gossip_cafe_rest28, 12, 44, 0, 27 },
    { "Your cafe is wet with steam.", kuro_v_gossip_cafe_rest29, 10, 118, 0, 28 },
    { "The pond approves.", kuro_v_gossip_cafe_rest30, 6, 84, 0, 18 },
    { "Like reading tides.", kuro_v_gossip_cafe_rest31, 10, 115, 0, 19 },
    { "Be patient with yourself.", kuro_v_gossip_cafe_rest32, 8, 100, 0, 25 },
    { "Cafes too, maybe.", kuro_v_gossip_cafe_rest33, 9, 54, 0, 17 },
    { "You serve once and smile.", kuro_v_gossip_cafe_rest34, 9, 98, 0, 25 },
    { "That's the whole craft.", kuro_v_gossip_cafe_rest35, 7, 39, 0, 23 },
    { "Mine at dawn.", kuro_v_gossip_cafe_rest36, 6, 113, 0, 13 },
    { "It brings you home too.", kuro_v_gossip_cafe_rest37, 8, 81, 0, 23 },
    { "So does a busy cafe, I hear.", kuro_v_gossip_cafe_rest38, 12, 26, 0, 28 },
    { "Small hands make steady work.", kuro_v_gossip_cafe_rest39, 11, 5, 0, 29 },
};
