static const CUnit kuro_v_smalltalk_rest[] = {
    { "So am I, mostly.", kuro_v_smalltalk_rest0, 9, 3, 0, 16 },
    { "Nets, and other things.", kuro_v_smalltalk_rest1, 10, 67, 0, 23 },
    { "Good signs.", kuro_v_smalltalk_rest2, 5, 91, 0, 11 },
    { "Morning dew does that.", kuro_v_smalltalk_rest3, 7, 112, 0, 22 },
    { "That is enough, mostly.", kuro_v_smalltalk_rest4, 9, 58, 0, 23 },
    { "The pond keeps its secrets.", kuro_v_smalltalk_rest5, 10, 89, 0, 27 },
    { "Sharp hooks catch thoughts too. Heh.", kuro_v_smalltalk_rest6, 17, 90, 0, 36 },
    { "Sleep can wait for rain.", kuro_v_smalltalk_rest7, 8, 52, 0, 24 },
    { "Mine stay small on purpose. Heh.", kuro_v_smalltalk_rest8, 13, 34, 0, 32 },
    { "I tie mine twice.", kuro_v_smalltalk_rest9, 6, 62, 0, 17 },
    { "Good for sitting.", kuro_v_smalltalk_rest10, 6, 83, 0, 17 },
    { "So it goes. Heh.", kuro_v_smalltalk_rest11, 10, 47, 0, 16 },
    { "I say that often enough.", kuro_v_smalltalk_rest12, 9, 27, 0, 24 },
    { "Mine is nearly there.", kuro_v_smalltalk_rest13, 7, 87, 0, 21 },
    { "Heh. The fish might.", kuro_v_smalltalk_rest14, 9, 44, 0, 20 },
    { "The fish are closer.", kuro_v_smalltalk_rest15, 7, 101, 0, 20 },
    { "Heh. Wobbly, but honest.", kuro_v_smalltalk_rest16, 14, 32, 0, 24 },
    { "We both keep working. Heh.", kuro_v_smalltalk_rest17, 11, 26, 0, 26 },
    { "It is only on time.", kuro_v_smalltalk_rest18, 6, 57, 0, 19 },
    { "Nothing much is enough. Heh.", kuro_v_smalltalk_rest19, 12, 109, 0, 28 },
    { "Fidgeting frightens the trout.", kuro_v_smalltalk_rest20, 14, 29, 0, 30 },
    { "Then he was gone. Heh.", kuro_v_smalltalk_rest21, 11, 113, 0, 22 },
    { "A greeting, perhaps.", kuro_v_smalltalk_rest22, 10, 95, 0, 20 },
    { "Old things hold when new ones won't. Heh.", kuro_v_smalltalk_rest23, 17, 37, 0, 41 },
    { "Sit down while you wait.", kuro_v_smalltalk_rest24, 8, 48, 0, 24 },
    { "I like that.", kuro_v_smalltalk_rest25, 4, 108, 0, 12 },
    { "Good, the pond is low.", kuro_v_smalltalk_rest26, 8, 36, 0, 22 },
    { "That is the whole trade, mostly.", kuro_v_smalltalk_rest27, 11, 24, 0, 32 },
    { "Both say rain tonight.", kuro_v_smalltalk_rest28, 9, 11, 0, 22 },
    { "He wins on speed. Heh.", kuro_v_smalltalk_rest29, 12, 59, 0, 22 },
    { "They teach patience cheaply enough.", kuro_v_smalltalk_rest30, 11, 16, 0, 35 },
    { "We fit the same water.", kuro_v_smalltalk_rest31, 8, 45, 0, 22 },
    { "So do my knees.", kuro_v_smalltalk_rest32, 8, 73, 0, 15 },
    { "That is why it is still here. Heh.", kuro_v_smalltalk_rest33, 13, 17, 0, 34 },
    { "It makes me damp and quiet, mostly.", kuro_v_smalltalk_rest34, 14, 42, 0, 35 },
    { "That is a comfort.", kuro_v_smalltalk_rest35, 7, 65, 0, 18 },
    { "I accept it gladly.", kuro_v_smalltalk_rest36, 10, 93, 0, 19 },
    { "Listen for it sometime.", kuro_v_smalltalk_rest37, 9, 21, 0, 23 },
    { "Heh. The fish like it that way.", kuro_v_smalltalk_rest38, 11, 0, 0, 31 },
    { "Slow, but it arrives.", kuro_v_smalltalk_rest39, 11, 68, 0, 21 },
};
